        "script": "const tier = $vars.customerTier || '';
const prodDown = $vars.productionDown === true;
const workaround = $vars.workaroundAvailable === true;
const impact = $vars.businessImpact || '';
const corrId = $vars.correlationId || '';

let sev;
if (prodDown && (tier === 'platinum' || impact === 'critical')) {
  sev = 'P1';
} else if (prodDown || (tier === 'platinum' && impact === 'high') || impact === 'critical') {
  sev = 'P2';
} else if (tier === 'gold' || tier === 'silver' || impact === 'high') {
  sev = 'P3';
} else {
  sev = 'P4';
}

if (workaround && sev === 'P1') { sev = 'P2'; }

const eng = sev === 'P1' || sev === 'P2';
const modeMap = { 'P1': 'immediate', 'P2': 'urgent', 'P3': 'standard', 'P4': 'low-priority' };
const mode = modeMap[sev];
const key = 'CET-' + corrId + '-' + sev;

return { severity: sev, engineeringNeeded: eng, responseMode: mode, caseKey: key };"

