const prodDown = $vars.productionDown === true;
const workaround = $vars.workaroundAvailable === true;

let sev;
if (tier === 'Enterprise' && prodDown && !workaround) {
  sev = 'Sev1';
} else if (prodDown && workaround) {
  sev = 'Sev2';
} else {
  sev = 'Sev3';
}

const eng = sev === 'Sev1' || sev === 'Sev2';

return { severity: sev, engineeringNeeded: eng, responseMode: 'Draft', caseKey: $vars.correlationId };"

